  p_Description_c949817c := 'Each contact''s IDs in other systems (for example a CRM or AMS), with the email, for matching rasa.io contacts to records elsewhere.';
  p_SQL_c949817c := '-- Each contact''s IDs in other systems (for example a CRM or AMS), with the email, so rasa.io
-- contacts can be matched to records elsewhere by ID as well as by email.
SELECT
    x.contact_id AS ContactID,
    c.email AS Email,
    x.system AS ExternalSystem,
    x.identifier AS ExternalID,
    x.system_identifier AS ExternalSystemIdentifier
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact_External_Identifier x
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = x.contact_id
';
  p_TechnicalDescription_c949817c := 'Contact_External_Identifier joined to Contact on contact_id for the email. One row per contact and external ID.';
  p_Status_c949817c := 'Approved';
