BEGIN
  p_ID_73473636 := '8B30286A-F9F5-4DFA-AE5C-F0CAA5D1E9B9';
  p_Name_73473636 := 'rasa.io - Contact Categories Across Newsletters';
  p_CategoryID_73473636 := '0FDEC5C4-B6B9-47CC-A8D5-F316DF611C4D';
  p_UserQuestion_73473636 := 'Which broad subject areas is each person interested in across all our newsletters, by email?';
  p_Description_73473636 := 'Each person''s interests at the category level (broader than topics), rolled up across every newsletter, with the email.';
  p_SQL_73473636 := '-- A person''s interests across every newsletter at the category level (broader than topics),
-- one row per contact and category, with the email. Merged the same way as the topic query.
SELECT
    t.contact_id AS ContactID,
    c.email AS Email,
    t.topic AS Category,
    SUM(t.num_clicks) AS Clicks,
    MAX(t.weight) AS Weight,
    COUNT(DISTINCT t.newsletter_id) AS Newsletters,
    MIN(t.first_click) AS FirstClick,
    MAX(t.last_click) AS LastClick
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter_Contact_Category t
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = t.contact_id
GROUP BY t.contact_id, c.email, t.topic
';
