-- Save MJ: Queries (core SP call only)
DO $mj$
DECLARE
  p_Name_8a1ad2fd VARCHAR(255);
  p_CategoryID_8a1ad2fd UUID;
  p_UserQuestion_8a1ad2fd TEXT;
  p_Description_8a1ad2fd TEXT;
  p_SQL_8a1ad2fd TEXT;
  p_TechnicalDescription_8a1ad2fd TEXT;
  p_OriginalSQL_8a1ad2fd TEXT;
