  p_SQLDialectID_8a1ad2fd UUID;
  p_Reusable_8a1ad2fd BOOLEAN;
  p_ID_8a1ad2fd UUID;
BEGIN
  p_Name_8a1ad2fd := 'rasa.io - Contact Topics by Newsletter';
  p_CategoryID_8a1ad2fd := '0FDEC5C4-B6B9-47CC-A8D5-F316DF611C4D';
  p_UserQuestion_8a1ad2fd := 'What topics is each contact interested in, in each newsletter, and what is their email?';
  p_Description_8a1ad2fd := 'Each contact''s topic interests per newsletter, from the topic clouds rasa.io builds from the articles they clicked, with the contact''s email and the newsletter''s name.';
  p_SQL_8a1ad2fd := '-- Each contact''s topics in each newsletter, with the contact''s email and the newsletter''s name.
-- contact_id is the rasa.io contact id: the same id in Contact, Newsletter Contact and the topic tables.
SELECT
    t.newsletter_id AS NewsletterID,
    n.name AS Newsletter,
    t.contact_id AS ContactID,
    c.email AS Email,
    t.topic AS Topic,
    t.num_clicks AS Clicks,
    t.weight AS Weight,
    t.first_click AS FirstClick,
    t.last_click AS LastClick,
    t.effective_date AS EffectiveDate
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter_Contact_Topic t
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = t.contact_id
LEFT JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter n ON n.id = t.newsletter_id
';
  p_TechnicalDescription_8a1ad2fd := 'Newsletter_Contact_Topic joined to Contact on contact_id = Contact.id for the email, and to Newsletter for its name. One row per newsletter, contact and topic. Weight is the topic''s share of the contact''s clicks in that newsletter. Only contacts who have clicked have rows.';
  p_Status_8a1ad2fd := 'Approved';
  p_QualityRank_8a1ad2fd := 8;
  p_ExecutionCostRank_8a1ad2fd := 3;
  p_UsesTemplate_8a1ad2fd := TRUE;
