  p_ID_41a0b455 UUID;
BEGIN
  p_Name_41a0b455 := 'rasa.io - Contact Topics Across Newsletters';
  p_CategoryID_41a0b455 := '0FDEC5C4-B6B9-47CC-A8D5-F316DF611C4D';
  p_UserQuestion_41a0b455 := 'What is each person interested in across all our newsletters, by email?';
  p_Description_41a0b455 := 'Each person''s topic interests rolled up across every newsletter, one row per contact and topic, with the email. Clicks are summed and the strongest weight is kept.';
  p_SQL_41a0b455 := '-- A person''s interests across every newsletter, one row per contact and topic, with the email.
-- Clicks are summed, the strongest per-newsletter weight is kept and the click window is widened,
-- the same way rasa.io merges a contact''s topics across an account''s newsletters.
SELECT
    t.contact_id AS ContactID,
    c.email AS Email,
    t.topic AS Topic,
    SUM(t.num_clicks) AS Clicks,
    MAX(t.weight) AS Weight,
    COUNT(DISTINCT t.newsletter_id) AS Newsletters,
    MIN(t.first_click) AS FirstClick,
    MAX(t.last_click) AS LastClick
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter_Contact_Topic t
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = t.contact_id
GROUP BY t.contact_id, c.email, t.topic
';
  p_TechnicalDescription_41a0b455 := 'Newsletter_Contact_Topic grouped by contact_id and topic, joined to Contact for the email. Clicks = SUM(num_clicks), Weight = MAX(weight), first/last click widened across newsletters: the same merge rasa.io uses for one contact''s topics. Rank a person''s interests by Clicks or Weight.';
  p_Status_41a0b455 := 'Approved';
