  p_Name_070171bd := 'rasa.io - Contact External IDs';
  p_CategoryID_070171bd := '0FDEC5C4-B6B9-47CC-A8D5-F316DF611C4D';
  p_UserQuestion_070171bd := 'What are each rasa.io contact''s IDs in our other systems?';
  p_Description_070171bd := 'Each contact''s IDs in other systems (for example a CRM or AMS), with the email, for matching rasa.io contacts to records elsewhere.';
  p_SQL_070171bd := '-- Each contact''s IDs in other systems (for example a CRM or AMS), with the email, so rasa.io
-- contacts can be matched to records elsewhere by ID as well as by email.
SELECT
    x.contact_id AS ContactID,
    c.email AS Email,
    x.system AS ExternalSystem,
    x.identifier AS ExternalID,
    x.system_identifier AS ExternalSystemIdentifier
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact_External_Identifier x
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = x.contact_id
';
  p_TechnicalDescription_070171bd := 'Contact_External_Identifier joined to Contact on contact_id for the email. One row per contact and external ID.';
