  p_ExecutionCostRank_97b8b4dc INTEGER;
  p_UsesTemplate_97b8b4dc BOOLEAN;
  p_AuditQueryRuns_97b8b4dc BOOLEAN;
  p_CacheEnabled_97b8b4dc BOOLEAN;
  p_CacheTTLMinutes_97b8b4dc INTEGER;
  p_CacheMaxSize_97b8b4dc INTEGER;
  p_EmbeddingVector_97b8b4dc TEXT;
  p_EmbeddingModelID_97b8b4dc UUID;
  p_CacheValidationSQL_97b8b4dc TEXT;
