  p_Reusable_97b8b4dc BOOLEAN;
  p_ID_97b8b4dc UUID;
BEGIN
  p_Name_97b8b4dc := 'rasa.io - Newsletter Engagement by Contact';
  p_CategoryID_97b8b4dc := '0FDEC5C4-B6B9-47CC-A8D5-F316DF611C4D';
  p_UserQuestion_97b8b4dc := 'How many opens and clicks has each contact made in each newsletter, and what is their email?';
  p_Description_97b8b4dc := 'Opens and clicks per contact and newsletter, with the contact''s email and first and last activity. Clicks rasa.io judged automated are left out.';
  p_SQL_97b8b4dc := '-- Opens and clicks per contact and newsletter, with the email from Contact (an event''s own email
-- can be empty). Clicks with confidence 0 looked automated to rasa.io and are left out.
SELECT
    a.newsletter_id AS NewsletterID,
    n.name AS Newsletter,
    a.contact_id AS ContactID,
    c.email AS Email,
    SUM(CASE WHEN a.action_type = ''open'' THEN 1 ELSE 0 END) AS Opens,
    SUM(CASE WHEN a.action_type = ''click'' AND a.confidence <> 0 THEN 1 ELSE 0 END) AS Clicks,
    MIN(a.created) AS FirstActivity,
    MAX(a.created) AS LastActivity
FROM {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter_Action a
INNER JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Contact c ON c.id = a.contact_id
LEFT JOIN {{ IntegrationSchema | default(''rasa'') | sqlIdentifier }}.Newsletter n ON n.id = a.newsletter_id
GROUP BY a.newsletter_id, n.name, a.contact_id, c.email
';
  p_TechnicalDescription_97b8b4dc := 'Newsletter_Action grouped by newsletter_id and contact_id, joined to Contact for the email (an event''s own email can be empty) and Newsletter for its name. Clicks with confidence 0 are excluded.';
  p_Status_97b8b4dc := 'Approved';
  p_QualityRank_97b8b4dc := 8;
  p_ExecutionCostRank_97b8b4dc := 3;
  p_UsesTemplate_97b8b4dc := TRUE;
  p_AuditQueryRuns_97b8b4dc := FALSE;
  p_CacheEnabled_97b8b4dc := FALSE;
